import json,glob,os,re
out={}
for f in sorted(glob.glob('products/research/parser-parity-paid-request/raw/*.json')):
    d=json.load(open(f,encoding='utf-8'))
    rows=[]
    for it in d.get('items',[]):
        b=(it.get('body') or '')
        rows.append({'url':it.get('html_url'),'title':it.get('title'),'created':it.get('created_at'),'updated':it.get('updated_at'),'comments':it.get('comments'),'assignees':len(it.get('assignees') or []),'labels':[l.get('name') for l in it.get('labels',[])],'money':re.findall(r'[$€£]\s?\d[\d,\.]*|\d+\s?(?:USD|USDC|EUR)',b)[:5],'body_head':re.sub(r'\s+',' ',b)[:350]})
    out[os.path.basename(f)]={'total_count':d.get('total_count'),'items':rows}
os.makedirs('products/research/parser-parity-paid-request',exist_ok=True)
json.dump(out,open('products/research/parser-parity-paid-request/extract.json','w'),indent=1,ensure_ascii=False)
print(json.dumps(out,ensure_ascii=False)[:9000])
